package main

import (
	"context"
	"crypto/ecdsa"
	"crypto/elliptic"
	"crypto/rand"
	"crypto/tls"
	"crypto/x509"
	"crypto/x509/pkix"
	"encoding/binary"
	"fmt"
	"io"
	"log"
	"math/big"
	"os"
	"time"

	"golang.org/x/net/quic"
)

func selfSigned() tls.Certificate {
	key, _ := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	tmpl := &x509.Certificate{
		SerialNumber: big.NewInt(1),
		Subject:      pkix.Name{CommonName: "localhost"},
		NotBefore:    time.Now().Add(-time.Hour),
		NotAfter:     time.Now().Add(24 * time.Hour),
		DNSNames:     []string{"localhost"},
	}
	der, err := x509.CreateCertificate(rand.Reader, tmpl, tmpl, &key.PublicKey, key)
	if err != nil {
		panic(err)
	}
	return tls.Certificate{Certificate: [][]byte{der}, PrivateKey: key}
}

func main() {
	cert := selfSigned()
	tlsConf := &tls.Config{
		Certificates: []tls.Certificate{cert},
		NextProtos:   []string{"perf"},
		GetConfigForClient: func(hi *tls.ClientHelloInfo) (*tls.Config, error) {
			log.Printf("ClientHello: SNI=%q ALPN=%v ciphers=%v curves=%v sigalgs=%v versions=%v", hi.ServerName, hi.SupportedProtos, hi.CipherSuites, hi.SupportedCurves, hi.SignatureSchemes, hi.SupportedVersions)
			return nil, nil
		},
		MinVersion: tls.VersionTLS13,
	}
	cfg := &quic.Config{TLSConfig: tlsConf}
	ep, err := quic.Listen("udp", os.Args[1], cfg)
	if err != nil {
		log.Fatal(err)
	}
	log.Printf("listening on %v", ep.LocalAddr())
	for {
		conn, err := ep.Accept(context.Background())
		if err != nil {
			log.Fatal(err)
		}
		log.Printf("conn from %v", conn.RemoteAddr())
		go func() {
			for {
				s, err := conn.AcceptStream(context.Background())
				if err != nil {
					log.Printf("accept stream: %v", err)
					return
				}
				go func() {
					var hdr [8]byte
					_, err := io.ReadFull(s, hdr[:])
					if err != nil {
						log.Printf("stream %d: hdr err %v", s.ID(), err)
						return
					}
					n, err := io.Copy(io.Discard, s)
					log.Printf("stream %d (ro=%v): hdr=%x (%d) body=%d err=%v", s.ID(), s.IsReadOnly(), hdr, binary.BigEndian.Uint64(hdr[:]), n, err)
					size := binary.BigEndian.Uint64(hdr[:])
					var w *quic.Stream = s
					if s.IsReadOnly() {
						w, err = conn.NewSendOnlyStream(context.Background())
						if err != nil {
							log.Printf("new stream err %v", err)
							return
						}
					}
					buf := make([]byte, 65536)
					for size > 0 {
						c := uint64(len(buf))
						if c > size {
							c = size
						}
						_, err := w.Write(buf[:c])
						if err != nil {
							log.Printf("write err %v", err)
							return
						}
						size -= c
					}
					w.Close()
					fmt.Fprintf(os.Stderr, "responded on %d\n", w.ID())
				}()
			}
		}()
	}
}
EOF
GOFLAGS=-mod=mod GOPROXY=off go build -o probe-server . && echo built"}

