{"command":"cd /workspace && cat > cli.go <<'EOF'
package main

import (
	"fmt"
	"net/netip"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// binName returns the program name as shown in usage lines.
func binName() string {
	if len(os.Args) == 0 || os.Args[0] == "" {
		return "executable"
	}
	return filepath.Base(os.Args[0])
}

func withBin(s string) string {
	return strings.ReplaceAll(s, "{BIN}", binName())
}

// usageError is a command line parsing failure (exit code 2).
type usageError struct {
	msg string
}

func (e *usageError) Error() string { return e.msg }

// helpRequest signals that help text should be printed (exit code 0).
type helpRequest struct {
	text string
}

func (h *helpRequest) Error() string { return "help" }

type argKind int

const (
	kindFlag argKind = iota
	kindU64
	kindU16
	kindSize
	kindSocketAddr
	kindIP
	kindPath
	kindCongestion
)

type argSpec struct {
	long      string // without leading dashes
	short     byte   // 0 if none
	valueName string // e.g. "DURATION"
	kind      argKind
}

func (a *argSpec) display() string {
	if a.kind == kindFlag {
		return "--" + a.long
	}
	return "--" + a.long + " <" + a.valueName + ">"
}

var commonArgs = []argSpec{
	{"send-buffer-size", 0, "SEND_BUFFER_SIZE", kindSize},
	{"recv-buffer-size", 0, "RECV_BUFFER_SIZE", kindSize},
	{"conn-stats", 0, "", kindFlag},
	{"keylog", 0, "", kindFlag},
	{"initial-mtu", 0, "INITIAL_MTU", kindU16},
	{"no-protection", 0, "", kindFlag},
	{"initial-rtt", 0, "INITIAL_RTT", kindU64},
	{"ack-frequency", 0, "", kindFlag},
	{"congestion", 0, "CONG_ALG", kindCongestion},
	{"stream-receive-window", 0, "STREAM_RECEIVE_WINDOW", kindSize},
	{"receive-window", 0, "RECEIVE_WINDOW", kindSize},
	{"send-window", 0, "SEND_WINDOW", kindSize},
	{"max-udp-payload-size", 0, "MAX_UDP_PAYLOAD_SIZE", kindU16},
	{"qlog", 0, "QLOG_FILE", kindPath},
}

var serverArgs = append([]argSpec{
	{"listen", 0, "LISTEN", kindSocketAddr},
	{"key", 'k', "KEY", kindPath},
	{"cert", 'c', "CERT", kindPath},
}, commonArgs...)

var clientArgs = append([]argSpec{
	{"ip", 0, "IP", kindIP},
	{"local-addr", 0, "LOCAL_ADDR", kindSocketAddr},
	{"uni-requests", 0, "UNI_REQUESTS", kindU64},
	{"bi-requests", 0, "BI_REQUESTS", kindU64},
	{"download-size", 0, "DOWNLOAD_SIZE", kindSize},
	{"upload-size", 0, "UPLOAD_SIZE", kindSize},
	{"duration", 0, "DURATION", kindU64},
	{"interval", 0, "INTERVAL", kindU64},
	{"json", 0, "JSON", kindPath},
}, commonArgs...)

var congestionValues = []string{"cubic", "bbr", "new-reno"}

const possibleCongestion = "  [possible values: cubic, bbr, new-reno]\n"

// parsedCommand holds the raw (validated) values of a subcommand invocation.
type parsedCommand struct {
	name       string
	values     map[string]string // long name -> raw value (flags map to "")
	positional []string
}

func (p *parsedCommand) has(long string) bool {
	_, ok := p.values[long]
	return ok
}

func (p *parsedCommand) get(long, def string) string {
	if v, ok := p.values[long]; ok {
		return v
	}
	return def
}

// ---------------------------------------------------------------------------
// String similarity (Jaro), used for "did you mean" suggestions.

func jaro(a, b string) float64 {
	ar := []rune(a)
	br := []rune(b)
	alen, blen := len(ar), len(br)
	if alen == 0 && blen == 0 {
		return 1.0
	}
	if alen == 0 || blen == 0 {
		return 0.0
	}
	searchRange := alen
	if blen > searchRange {
		searchRange = blen
	}
	searchRange /= 2
	if searchRange > 0 {
		searchRange--
	}
	aflags := make([]bool, alen)
	bflags := make([]bool, blen)
	matches := 0
	for i := 0; i < alen; i++ {
		minBound := 0
		if i > searchRange {
			minBound = i - searchRange
		}
		maxBound := i + searchRange + 1
		if maxBound > blen {
			maxBound = blen
		}
		for j := 0; j < maxBound; j++ {
			if minBound <= j && ar[i] == br[j] && !bflags[j] {
				aflags[i] = true
				bflags[j] = true
				matches++
				break
			}
		}
	}
	if matches == 0 {
		return 0.0
	}
	transpositions := 0
	bi := 0
	for i := 0; i < alen; i++ {
		if !aflags[i] {
			continue
		}
		for bi < blen && !bflags[bi] {
			bi++
		}
		if bi < blen {
			if ar[i] != br[bi] {
				transpositions++
			}
			bi++
		}
	}
	transpositions /= 2
	m := float64(matches)
	return (m/float64(alen) + m/float64(blen) + (m-float64(transpositions))/m) / 3.0
}

// didYouMean returns candidates with similarity > 0.7, sorted by ascending confidence.
func didYouMean(v string, candidates []string) []string {
	type cand struct {
		conf float64
		s    string
	}
	var cs []cand
	for _, c := range candidates {
		conf := jaro(v, c)
		if conf > 0.7 {
			cs = append(cs, cand{conf, c})
		}
	}
	sort.SliceStable(cs, func(i, j int) bool { return cs[i].conf < cs[j].conf })
	out := make([]string, 0, len(cs))
	for _, c := range cs {
		out = append(out, c.s)
	}
	return out
}

func quoteList(items []string) string {
	q := make([]string, len(items))
	for i, s := range items {
		q[i] = "'" + s + "'"
	}
	return strings.Join(q, ", ")
}

// ---------------------------------------------------------------------------

const moreInfo = "For more information, try '--help'.\n"

func topUsage() string {
	return fmt.Sprintf("Usage: %s <COMMAND>\n", binName())
}

func subUsage(cmd string) string {
	if cmd == "server" {
		return fmt.Sprintf("Usage: %s server [OPTIONS]\n", binName())
	}
	return fmt.Sprintf("Usage: %s client [OPTIONS] [HOST]\n", binName())
}

// usageWith renders a usage line that highlights specific arguments (clap style).
func usageWith(cmd string, args []string) string {
	s := fmt.Sprintf("Usage: %s %s", binName(), cmd)
	for _, a := range args {
		s += " " + a
	}
	if cmd == "client" {
		s += " [HOST]"
	}
	return s + "\n"
}

func errUnexpectedArgument(tok string, cmd string, hasPositional bool, suggestion *argSpec) *usageError {
	var b strings.Builder
	fmt.Fprintf(&b, "error: unexpected argument '%s' found\n", tok)
	if suggestion != nil {
		fmt.Fprintf(&b, "\n  tip: a similar argument exists: '--%s'\n", suggestion.long)
		b.WriteString("\n" + usageWith(cmd, []string{suggestion.display()}))
	} else {
		if hasPositional && strings.HasPrefix(tok, "-") {
			fmt.Fprintf(&b, "\n  tip: to pass '%s' as a value, use '-- %s'\n", tok, tok)
		}
		b.WriteString("\n" + subUsage(cmd))
	}
	b.WriteString("\n" + moreInfo)
	return &usageError{b.String()}
}

func errValueRequired(spec *argSpec) *usageError {
	s := fmt.Sprintf("error: a value is required for '%s' but none was supplied\n", spec.display())
	if spec.kind == kindCongestion {
		s += possibleCongestion
	}
	return &usageError{s + "\n" + moreInfo}
}

func errInvalidValue(spec *argSpec, val, msg string) *usageError {
	s := fmt.Sprintf("error: invalid value '%s' for '%s': %s\n", val, spec.display(), msg)
	return &usageError{s + "\n" + moreInfo}
}

func errMultiple(cmd string, spec *argSpec) *usageError {
	s := fmt.Sprintf("error: the argument '%s' cannot be used multiple times\n", spec.display())
	return &usageError{s + "\n" + subUsage(cmd) + "\n" + moreInfo}
}

func findLong(specs []argSpec, long string) *argSpec {
	for i := range specs {
		if specs[i].long == long {
			return &specs[i]
		}
	}
	return nil
}

func findShort(specs []argSpec, c byte) *argSpec {
	for i := range specs {
		if specs[i].short != 0 && specs[i].short == c {
			return &specs[i]
		}
	}
	return nil
}

// isFlagLike reports whether a token would be interpreted as a flag by clap
// (and thus cannot be consumed as an option value).
func isFlagLike(tok string) bool {
	return len(tok) > 1 && strings.HasPrefix(tok, "-")
}

// isKnownFlagToken reports whether a flag-like token refers to a known argument.
func isKnownFlagToken(specs []argSpec, tok string) bool {
	if tok == "--" {
		return true
	}
	if strings.HasPrefix(tok, "--") {
		name := tok[2:]
		if i := strings.IndexByte(name, '='); i >= 0 {
			name = name[:i]
		}
		return name == "help" || findLong(specs, name) != nil
	}
	if strings.HasPrefix(tok, "-") && len(tok) > 1 {
		c := tok[1]
		return c == 'h' || findShort(specs, c) != nil
	}
	return false
}

// validateValue checks a raw value against the argument type, returning the
// clap-style error message on failure.
func validateValue(spec *argSpec, val string) *usageError {
	switch spec.kind {
	case kindU64:
		if _, err := parseRustU64(val); err != nil {
			return errInvalidValue(spec, val, err.Error())
		}
	case kindU16:
		if _, err := parseRustU16(val); err != nil {
			return errInvalidValue(spec, val, err.Error())
		}
	case kindSize:
		if _, err := parseSize(val); err != nil {
			return errInvalidValue(spec, val, err.Error())
		}
	case kindSocketAddr:
		if _, err := parseSocketAddr(val); err != nil {
			return errInvalidValue(spec, val, "invalid socket address syntax")
		}
	case kindIP:
		if _, err := parseIPAddr(val); err != nil {
			return errInvalidValue(spec, val, "invalid IP address syntax")
		}
	case kindPath:
		if val == "" {
			return errValueRequired(spec)
		}
	case kindCongestion:
		if val == "" {
			return errValueRequired(spec)
		}
		ok := false
		for _, c := range congestionValues {
			if c == val {
				ok = true
			}
		}
		if !ok {
			s := fmt.Sprintf("error: invalid value '%s' for '%s'\n", val, spec.display())
			s += possibleCongestion
			sugg := didYouMean(val, congestionValues)
			if len(sugg) == 1 {
				s += fmt.Sprintf("\n  tip: a similar value exists: '%s'\n", sugg[0])
			} else if len(sugg) > 1 {
				s += fmt.Sprintf("\n  tip: some similar values exist: %s\n", quoteList(sugg))
			}
			return &usageError{s + "\n" + moreInfo}
		}
	}
	return nil
}

// parseSubcommand parses the arguments of the server/client subcommands.
func parseSubcommand(cmd string, args []string) (*parsedCommand, error) {
	var specs []argSpec
	hasPositional := false
	longHelp, shortHelp := "", ""
	if cmd == "server" {
		specs = serverArgs
		longHelp, shortHelp = helpServerLong, helpServerShort
	} else {
		specs = clientArgs
		hasPositional = true
		longHelp, shortHelp = helpClientLong, helpClientShort
	}
	longNames := make([]string, 0, len(specs)+1)
	for _, s := range specs {
		longNames = append(longNames, s.long)
	}
	longNames = append(longNames, "help")

	pc := &parsedCommand{name: cmd, values: map[string]string{}}
	afterDD := false

	suggestFor := func(name string) *argSpec {
		cands := didYouMean(name, longNames)
		if len(cands) == 0 {
			return nil
		}
		best := cands[len(cands)-1]
		if best == "help" {
			return &argSpec{long: "help", kind: kindFlag}
		}
		return findLong(specs, best)
	}

	// takeValue handles an option that needs a value from the following token.
	takeValue := func(spec *argSpec, i *int) (string, error) {
		if *i+1 < len(args) {
			next := args[*i+1]
			if !isFlagLike(next) {
				*i++
				return next, nil
			}
			if !isKnownFlagToken(specs, next) {
				// clap reports the unknown following token first
				if strings.HasPrefix(next, "--") {
					name := next[2:]
					if k := strings.IndexByte(name, '='); k >= 0 {
						name = name[:k]
					}
					return "", errUnexpectedArgument(next, cmd, hasPositional, suggestFor(name))
				}
				return "", errUnexpectedArgument(next, cmd, hasPositional, nil)
			}
		}
		return "", errValueRequired(spec)
	}

	for i := 0; i < len(args); i++ {
		tok := args[i]
		if !afterDD && tok == "--" {
			afterDD = true
			continue
		}
		if !afterDD && strings.HasPrefix(tok, "--") {
			name := tok[2:]
			var val *string
			if k := strings.IndexByte(name, '='); k >= 0 {
				v := name[k+1:]
				val = &v
				name = name[:k]
			}
			if name == "help" {
				return nil, &helpRequest{withBin(longHelp)}
			}
			spec := findLong(specs, name)
			if spec == nil {
				return nil, errUnexpectedArgument(tok, cmd, hasPositional, suggestFor(name))
			}
			if spec.kind == kindFlag {
				if val != nil {
					s := fmt.Sprintf("error: unexpected value '%s' for '--%s' found; no more were expected\n", *val, spec.long)
					return nil, &usageError{s + "\n" + usageWith(cmd, []string{spec.display()}) + "\n" + moreInfo}
				}
				if pc.has(spec.long) {
					return nil, errMultiple(cmd, spec)
				}
				pc.values[spec.long] = ""
				continue
			}
			var v string
			if val != nil {
				v = *val
			} else {
				var err error
				v, err = takeValue(spec, &i)
				if err != nil {
					return nil, err
				}
			}
			if pc.has(spec.long) {
				return nil, errMultiple(cmd, spec)
			}
			if e := validateValue(spec, v); e != nil {
				return nil, e
			}
			pc.values[spec.long] = v
			continue
		}
		if !afterDD && len(tok) > 1 && strings.HasPrefix(tok, "-") {
			c := tok[1]
			if c == 'h' {
				return nil, &helpRequest{withBin(shortHelp)}
			}
			spec := findShort(specs, c)
			if spec == nil {
				return nil, errUnexpectedArgument(tok, cmd, hasPositional, nil)
			}
			rest := tok[2:]
			var v string
			if rest != "" {
				if rest[0] == '=' {
					rest = rest[1:]
				}
				v = rest
			} else {
				var err error
				v, err = takeValue(spec, &i)
				if err != nil {
					return nil, err
				}
			}
			if pc.has(spec.long) {
				return nil, errMultiple(cmd, spec)
			}
			if e := validateValue(spec, v); e != nil {
				return nil, e
			}
			pc.values[spec.long] = v
			continue
		}
		// positional
		if hasPositional && len(pc.positional) == 0 {
			pc.positional = append(pc.positional, tok)
			continue
		}
		return nil, errUnexpectedArgument(tok, cmd, false, nil)
	}

	if cmd == "server" {
		hasKey, hasCert := pc.has("key"), pc.has("cert")
		if hasKey != hasCert {
			var b strings.Builder
			b.WriteString("error: the following required arguments were not provided:\n")
			if hasKey {
				b.WriteString("  --cert <CERT>\n\n")
				fmt.Fprintf(&b, "Usage: %s server --key <KEY> --cert <CERT>\n", binName())
			} else {
				b.WriteString("  --key <KEY>\n\n")
				fmt.Fprintf(&b, "Usage: %s server --cert <CERT> --key <KEY>\n", binName())
			}
			b.WriteString("\n" + moreInfo)
			return nil, &usageError{b.String()}
		}
	}
	return pc, nil
}

var subcommandNames = []string{"server", "client", "help"}

func errUnrecognizedSubcommand(name string, usage string) *usageError {
	var b strings.Builder
	fmt.Fprintf(&b, "error: unrecognized subcommand '%s'\n", name)
	sugg := didYouMean(name, subcommandNames)
	if len(sugg) == 1 {
		fmt.Fprintf(&b, "\n  tip: a similar subcommand exists: '%s'\n", sugg[0])
	} else if len(sugg) > 1 {
		fmt.Fprintf(&b, "\n  tip: some similar subcommands exist: %s\n", quoteList(sugg))
	}
	b.WriteString("\n" + usage + "\n" + moreInfo)
	return &usageError{b.String()}
}

// parseCommandLine parses the full command line (without argv[0]).
// It returns the parsed subcommand, or a *helpRequest / *usageError.
func parseCommandLine(args []string) (*parsedCommand, error) {
	if len(args) == 0 {
		return nil, &usageError{withBin(helpTop)}
	}
	first := args[0]
	switch {
	case first == "-h" || first == "--help":
		return nil, &helpRequest{withBin(helpTop)}
	case first == "server" || first == "client":
		return parseSubcommand(first, args[1:])
	case first == "help":
		rest := args[1:]
		if len(rest) == 0 {
			return nil, &helpRequest{withBin(helpTop)}
		}
		switch rest[0] {
		case "server":
			if len(rest) > 1 {
				return nil, errUnrecognizedSubcommand(rest[1], subUsage("server"))
			}
			return nil, &helpRequest{withBin(helpServerLong)}
		case "client":
			if len(rest) > 1 {
				return nil, errUnrecognizedSubcommand(rest[1], subUsage("client"))
			}
			return nil, &helpRequest{withBin(helpClientLong)}
		case "help":
			if len(rest) > 1 {
				return nil, errUnrecognizedSubcommand(rest[1], fmt.Sprintf("Usage: %s help [COMMAND]...\n", binName()))
			}
			return nil, &helpRequest{withBin(helpHelp)}
		default:
			return nil, errUnrecognizedSubcommand(rest[0], topUsage())
		}
	case strings.HasPrefix(first, "--"):
		name := first[2:]
		if k := strings.IndexByte(name, '='); k >= 0 {
			name = name[:k]
		}
		var b strings.Builder
		fmt.Fprintf(&b, "error: unexpected argument '%s' found\n", first)
		if len(didYouMean(name, []string{"help"})) > 0 {
			b.WriteString("\n  tip: a similar argument exists: '--help'\n")
			fmt.Fprintf(&b, "\nUsage: %s --help <COMMAND>\n", binName())
		} else {
			b.WriteString("\n" + topUsage())
		}
		b.WriteString("\n" + moreInfo)
		return nil, &usageError{b.String()}
	case strings.HasPrefix(first, "-") && len(first) > 1:
		s := fmt.Sprintf("error: unexpected argument '%s' found\n", first)
		return nil, &usageError{s + "\n" + topUsage() + "\n" + moreInfo}
	default:
		return nil, errUnrecognizedSubcommand(first, topUsage())
	}
}

// ---------------------------------------------------------------------------
// Rust-compatible value parsers.

type parseIntError struct{ msg string }

func (e *parseIntError) Error() string { return e.msg }

var (
	errIntEmpty    = &parseIntError{"cannot parse integer from empty string"}
	errIntDigit    = &parseIntError{"invalid digit found in string"}
	errIntTooLarge = &parseIntError{"number too large to fit in target type"}
	errIntTooSmall = &parseIntError{"number too small to fit in target type"}
)

// parseRustU64 mirrors u64::from_str.
func parseRustU64(s string) (uint64, error) {
	if s == "" {
		return 0, errIntEmpty
	}
	if s[0] == '+' {
		s = s[1:]
		if s == "" {
			return 0, errIntDigit
		}
	}
	var v uint64
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c < '0' || c > '9' {
			return 0, errIntDigit
		}
		d := uint64(c - '0')
		if v > (^uint64(0)-d)/10 {
			return 0, errIntTooLarge
		}
		v = v*10 + d
	}
	return v, nil
}

// parseRustI64 mirrors i64::from_str.
func parseRustI64(s string) (int64, error) {
	if s == "" {
		return 0, errIntEmpty
	}
	neg := false
	if s[0] == '+' || s[0] == '-' {
		neg = s[0] == '-'
		s = s[1:]
		if s == "" {
			return 0, errIntDigit
		}
	}
	var v uint64
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c < '0' || c > '9' {
			return 0, errIntDigit
		}
		d := uint64(c - '0')
		if neg {
			if v > (uint64(1)<<63-d)/10 {
				return 0, errIntTooSmall
			}
		} else {
			if v > (uint64(1)<<63-1-d)/10 {
				return 0, errIntTooLarge
			}
		}
		v = v*10 + d
	}
	if neg {
		return -int64(v), nil
	}
	return int64(v), nil
}

// parseRustU16 mirrors clap's ranged i64 parser targeting u16.
func parseRustU16(s string) (uint16, error) {
	v, err := parseRustI64(s)
	if err != nil {
		return 0, err
	}
	if v < 0 || v > 65535 {
		return 0, &parseIntError{fmt.Sprintf("%d is not in 0..=65535", v)}
	}
	return uint16(v), nil
}

// parseSize parses a byte size with optional k/M/G/T suffix.
func parseSize(s string) (uint64, error) {
	s = strings.TrimSpace(s)
	var mult uint64 = 1
	if n := len(s); n > 0 {
		switch s[n-1] {
		case 'k':
			mult = 1 << 10
			s = s[:n-1]
		case 'M':
			mult = 1 << 20
			s = s[:n-1]
		case 'G':
			mult = 1 << 30
			s = s[:n-1]
		case 'T':
			mult = 1 << 40
			s = s[:n-1]
		}
	}
	v, err := parseRustU64(s)
	if err != nil {
		return 0, err
	}
	return v * mult, nil
}

// parseSocketAddr mirrors Rust's SocketAddr::from_str (requires a port).
func parseSocketAddr(s string) (netip.AddrPort, error) {
	ap, err := netip.ParseAddrPort(s)
	if err != nil {
		return netip.AddrPort{}, err
	}
	// Rust rejects zone identifiers on IPv6 literals in socket addresses
	// unless numeric; keep netip behaviour.
	return ap, nil
}

// parseIPAddr mirrors Rust's IpAddr::from_str.
func parseIPAddr(s string) (netip.Addr, error) {
	a, err := netip.ParseAddr(s)
	if err != nil {
		return netip.Addr{}, err
	}
	if a.Zone() != "" {
		return netip.Addr{}, fmt.Errorf("invalid")
	}
	return a, nil
}
EOF
echo done"}

