// Log levels (ordered from most to least verbose).
type logLevel int

const (
	levelTrace logLevel = iota
	levelDebug
	levelInfo
	levelWarn
	levelError
	levelOff
)

// stdoutMu serializes all writes to standard output so that log lines and
// report blocks never interleave.
var stdoutMu sync.Mutex

func writeStdout(s string) {
	stdoutMu.Lock()
	io.WriteString(os.Stdout, s)
	stdoutMu.Unlock()
}

// filterDirective is a single `target=level` directive.
type filterDirective struct {
	target string // "" for global
	level  logLevel
	span   bool // directive scoped to a span: never matches plain events
}

type logFilter struct {
	directives []filterDirective
}

func parseLevelName(s string) (logLevel, bool) {
	switch strings.ToLower(s) {
	case "trace", "5":
		return levelTrace, true
	case "debug", "4":
		return levelDebug, true
	case "info", "3":
		return levelInfo, true
	case "warn", "2":
		return levelWarn, true
	case "error", "1":
		return levelError, true
	case "off", "0":
		return levelOff, true
	}
	return 0, false
}

// parseLogFilter parses a RUST_LOG style directive list. It returns false if
// the directive list is invalid.
func parseLogFilter(spec string) (*logFilter, bool) {
	f := &logFilter{}
	for _, part := range strings.Split(spec, ",") {
		if part == "" {
			continue
		}
		if lvl, ok := parseLevelName(part); ok {
			f.add(filterDirective{target: "", level: lvl})
			continue
		}
		target := part
		levelStr := ""
		hasLevel := false
		if k := strings.IndexByte(part, '='); k >= 0 {
			target = part[:k]
			levelStr = part[k+1:]
			hasLevel = true
		}
		span := false
		if k := strings.IndexByte(target, '['); k >= 0 {
			if !strings.HasSuffix(target, "]") {
				return nil, false
			}
			target = target[:k]
			span = true
		}
		if strings.HasPrefix(target, " ") || strings.HasPrefix(target, "\t") {
			return nil, false
		}
		if hasLevel && !span && target == "" {
			return nil, false
		}
		lvl := levelTrace
		if hasLevel && levelStr != "" {
			l, ok := parseLevelName(levelStr)
			if !ok {
				return nil, false
			}
			lvl = l
		}
		f.add(filterDirective{target: target, level: lvl, span: span})
	}
	return f, true
}

func (f *logFilter) add(d filterDirective) {
	for i := range f.directives {
		if f.directives[i].target == d.target && f.directives[i].span == d.span {
			f.directives[i] = d
			return
		}
	}
	f.directives = append(f.directives, d)
}

// enabled reports whether an event with the given target and level passes.
func (f *logFilter) enabled(target string, lvl logLevel) bool {
	best := -1
	bestLen := -1
	for i, d := range f.directives {
		if d.span {
			continue
		}
		if d.target == "" || strings.HasPrefix(target, d.target) {
			if len(d.target) > bestLen {
				bestLen = len(d.target)
				best = i
			}
		}
	}
	if best < 0 {
		return false
	}
	return lvl >= f.directives[best].level && f.directives[best].level != levelOff
}

var globalFilter *logFilter

func initLogging() {
	spec, ok := os.LookupEnv("RUST_LOG")
	if ok {
		if f, valid := parseLogFilter(spec); valid {
			globalFilter = f
			return
		}
	}
	globalFilter, _ = parseLogFilter("warn")
}

func levelLabel(lvl logLevel) string {
	switch lvl {
	case levelTrace:
		return "\x1b[35mTRACE\x1b[0m"
	case levelDebug:
		return "\x1b[34mDEBUG\x1b[0m"
	case levelInfo:
		return "\x1b[32m INFO\x1b[0m"
	case levelWarn:
		return "\x1b[33m WARN\x1b[0m"
	default:
		return "\x1b[31mERROR\x1b[0m"
	}
}

func logEnabled(target string, lvl logLevel) bool {
	if globalFilter == nil {
		return lvl >= levelWarn
	}
	return globalFilter.enabled(target, lvl)
}

func logEvent(target string, lvl logLevel, format string, args ...interface{}) {
	if !logEnabled(target, lvl) {
		return
	}
	msg := fmt.Sprintf(format, args...)
	ts := time.Now().UTC().Format("2006-01-02T15:04:05.000000Z")
	line := fmt.Sprintf("\x1b[2m%s\x1b[0m %s \x1b[2m%s\x1b[0m\x1b[2m:\x1b[0m %s\n", ts, levelLabel(lvl), target, msg)
	writeStdout(line)
}

func logError(target, format string, args ...interface{}) {
	logEvent(target, levelError, format, args...)
}

func logWarn(target, format string, args ...interface{}) {
	logEvent(target, levelWarn, format, args...)
}

func logInfo(target, format string, args ...interface{}) {
	logEvent(target, levelInfo, format, args...)
}

func logDebug(target, format string, args ...interface{}) {
	logEvent(target, levelDebug, format, args...)
}
