package main

import (
	"math"
	"math/bits"
	"sort"
)

// hdrHistogram is a high dynamic range histogram with 3 significant digits
// of value precision, able to record any uint64 value.
type hdrHistogram struct {
	counts     map[int]uint64
	totalCount uint64
}

const (
	hdrSubBucketHalfCountMagnitude = 10
	hdrSubBucketCount              = 1 << (hdrSubBucketHalfCountMagnitude + 1) // 2048
	hdrSubBucketHalfCount          = hdrSubBucketCount / 2
	hdrSubBucketMask               = uint64(hdrSubBucketCount - 1)
)

func newHdrHistogram() *hdrHistogram {
	return &hdrHistogram{counts: map[int]uint64{}}
}

func hdrBucketIndex(v uint64) int {
	pow2ceil := 64 - bits.LeadingZeros64(v|hdrSubBucketMask)
	return pow2ceil - (hdrSubBucketHalfCountMagnitude + 1)
}

func hdrSubBucketIndex(v uint64, bucket int) int {
	return int(v >> uint(bucket))
}

func hdrCountsIndex(v uint64) int {
	b := hdrBucketIndex(v)
	sb := hdrSubBucketIndex(v, b)
	return ((b + 1) << hdrSubBucketHalfCountMagnitude) + (sb - hdrSubBucketHalfCount)
}

func hdrValueFromIndex(idx int) uint64 {
	b := (idx >> hdrSubBucketHalfCountMagnitude) - 1
	sb := (idx & (hdrSubBucketHalfCount - 1)) + hdrSubBucketHalfCount
	if b < 0 {
		sb -= hdrSubBucketHalfCount
		b = 0
	}
	return uint64(sb) << uint(b)
}

func hdrEquivalentRange(v uint64) uint64 {
	b := hdrBucketIndex(v)
	sb := hdrSubBucketIndex(v, b)
	if sb >= hdrSubBucketCount {
		b++
	}
	return uint64(1) << uint(b)
}

func hdrLowestEquivalent(v uint64) uint64 {
	b := hdrBucketIndex(v)
	sb := hdrSubBucketIndex(v, b)
	return uint64(sb) << uint(b)
}

func hdrHighestEquivalent(v uint64) uint64 {
	lo := hdrLowestEquivalent(v)
	r := hdrEquivalentRange(v)
	if lo > math.MaxUint64-r {
		return math.MaxUint64
	}
	return lo + r - 1
}

func hdrMedianEquivalent(v uint64) uint64 {
	lo := hdrLowestEquivalent(v)
	half := hdrEquivalentRange(v) >> 1
	if lo > math.MaxUint64-half {
		return math.MaxUint64
	}
	return lo + half
}

func (h *hdrHistogram) record(v uint64) {
	h.counts[hdrCountsIndex(v)]++
	h.totalCount++
}

func (h *hdrHistogram) sortedIndices() []int {
	idx := make([]int, 0, len(h.counts))
	for i := range h.counts {
		idx = append(idx, i)
	}
	sort.Ints(idx)
	return idx
}

// mean returns the arithmetic mean of recorded values (bucket median equivalents).
