// fmtDuration renders a duration with two decimals and an adaptive unit.
func fmtDuration(d time.Duration) string {
	nanos := float64(d.Nanoseconds())
	switch {
	case d < time.Microsecond:
		return fmt.Sprintf("%.2fns", nanos)
	case d < time.Millisecond:
		return fmt.Sprintf("%.2fµs", nanos/1e3)
	case d < time.Second:
		return fmt.Sprintf("%.2fms", nanos/1e6)
	default:
		return fmt.Sprintf("%.2fs", nanos/1e9)
	}
}

// fmtRustDurationDebug mimics Rust's `{:?}` formatting of core::time::Duration.
func fmtRustDurationDebug(d time.Duration) string {
	if d < 0 {
		d = 0
	}
	secs := uint64(d / time.Second)
	nanos := uint64(d % time.Second)
	var integer, frac uint64
	var prec int
	var suffix string
	switch {
	case secs > 0:
		integer, frac, prec, suffix = secs, nanos, 9, "s"
	case nanos >= 1_000_000:
		integer, frac, prec, suffix = nanos/1_000_000, nanos%1_000_000, 6, "ms"
	case nanos >= 1_000:
		integer, frac, prec, suffix = nanos/1_000, nanos%1_000, 3, "µs"
	default:
		integer, frac, prec, suffix = nanos, 0, 0, "ns"
	}
	s := strconv.FormatUint(integer, 10)
	if frac > 0 {
		f := fmt.Sprintf("%0*d", prec, frac)
		f = strings.TrimRight(f, "0")
		s += "." + f
	}
	return s + suffix
}

// fmtRustF64 mimics serde_json's (ryu based) formatting of finite f64 values.
func fmtRustF64(v float64) string {
	if math.IsNaN(v) || math.IsInf(v, 0) {
		return "null"
	}
	if v == 0 {
		if math.Signbit(v) {
			return "-0.0"
		}
		return "0.0"
	}
	neg := v < 0
	if neg {
		v = -v
	}
	e := strconv.FormatFloat(v, 'e', -1, 64) // d.dddde±XX
	mant, expStr, _ := strings.Cut(e, "e")
	exp10, _ := strconv.Atoi(expStr)
	digits := strings.Replace(mant, ".", "", 1)
	digits = strings.TrimRight(digits, "0")
	if digits == "" {
		digits = "0"
	}
	olength := len(digits)
	// value = digits * 10^exponent
	exponent := exp10 - (olength - 1)
	kk := olength + exponent
	var out string
	switch {
	case exponent >= 0 && kk <= 16:
		out = digits + strings.Repeat("0", exponent) + ".0"
	case 0 < kk && kk <= 16:
		out = digits[:kk] + "." + digits[kk:]
	case -5 < kk && kk <= 0:
		out = "0." + strings.Repeat("0", -kk) + digits
	case olength == 1:
		out = digits + "e" + strconv.Itoa(exponent)
	default:
		out = digits[:1] + "." + digits[1:] + "e" + strconv.Itoa(kk-1)
	}
	if neg {
		out = "-" + out
	}
	return out
}

// capitalizeFirst upper-cases the first letter (Rust/glibc style OS error text).
func capitalizeFirst(s string) string {
	if s == "" {
		return s
	}
	return strings.ToUpper(s[:1]) + s[1:]
}
