package main

import (
	"fmt"
	"math"
	"strings"
	"time"
)

type streamEntry struct {
	id       uint64
	sender   bool
	bytes    uint64
	finished bool
}

type streamJSON struct {
	id            uint64
	start, end    float64
	seconds       float64
	bytes         uint64
	bitsPerSecond float64
	sender        bool
}

type intervalJSON struct {
	streams []streamJSON
	sum     streamJSON
}

// perfStats accumulates request metrics for the client.
type perfStats struct {
	start     time.Time
	startUnix int64

	requests   uint64
	uploadDur  *hdrHistogram
	downDur    *hdrHistogram
	fbl        *hdrHistogram
	uploadTp   *hdrHistogram
	downloadTp *hdrHistogram

	streams   []*streamEntry
	intervals []intervalJSON
}

func newPerfStats(start time.Time) *perfStats {
	return &perfStats{
		start:      start,
		startUnix:  time.Now().Unix(),
		uploadDur:  newHdrHistogram(),
		downDur:    newHdrHistogram(),
		fbl:        newHdrHistogram(),
		uploadTp:   newHdrHistogram(),
		downloadTp: newHdrHistogram(),
	}
}

// throughput computes bytes per second saturating like Rust's `as u64`.
func throughput(bytes uint64, d time.Duration) uint64 {
	secs := d.Seconds()
	v := float64(bytes) / secs
	if math.IsNaN(v) {
		return 0
	}
	if v >= 18446744073709551615.0 || math.IsInf(v, 1) {
		return math.MaxUint64
	}
	if v <= 0 {
		return 0
	}
	return uint64(v)
}

func (s *perfStats) streamStarted(id uint64, sender bool) *streamEntry {
	e := &streamEntry{id: id, sender: sender}
	s.streams = append(s.streams, e)
	return e
}

func (s *perfStats) recordUpload(d time.Duration, bytes uint64) {
	s.uploadDur.record(uint64(d / time.Microsecond))
	s.uploadTp.record(throughput(bytes, d))
}

func (s *perfStats) recordDownload(d, firstByte time.Duration, bytes uint64) {
	s.downDur.record(uint64(d / time.Microsecond))
	s.fbl.record(uint64(firstByte / time.Microsecond))
	s.downloadTp.record(throughput(bytes, d))
	s.requests++
}

func rowValues(h *hdrHistogram) []uint64 {
	return []uint64{
		uint64(h.mean()),
		h.valueAtQuantile(0.0),
		h.valueAtQuantile(0.1),
		h.valueAtQuantile(0.5),
		h.valueAtQuantile(0.9),
		h.valueAtQuantile(1.0),
	}
}

func meanToU64(m float64) uint64 {
	if m >= 18446744073709551615.0 {
		return math.MaxUint64
	}
	if m <= 0 {
		return 0
	}
	return uint64(m)
}

func durCell(v uint64) string {
	return fmtDuration(time.Duration(v) * time.Microsecond)
}

func tpCell(v uint64) string {
	return fmt.Sprintf("%.2f Mb/s", float64(v)*8/1e6)
}

// report renders the periodic statistics block.
func (s *perfStats) report(now time.Time) string {
	var b strings.Builder
	elapsed := now.Sub(s.start)
	rps := float64(s.requests) / elapsed.Seconds()
	if math.IsNaN(rps) || math.IsInf(rps, 0) {
		rps = 0
	}
	b.WriteString("Overall stats:\n")
	fmt.Fprintf(&b, "RPS: %.2f (%d requests in %s)\n", rps, s.requests, fmtDuration(elapsed))
	b.WriteString("\nStream metrics:\n\n")
	b.WriteString("      │ Upload Duration │ Download Duration | FBL        | Upload Throughput | Download Throughput\n")
	b.WriteString("──────┼─────────────────┼───────────────────┼────────────┼───────────────────┼────────────────────\n")
	labels := []string{"AVG", "P0", "P10", "P50", "P90", "P100"}
	hists := []*hdrHistogram{s.uploadDur, s.downDur, s.fbl, s.uploadTp, s.downloadTp}
	cols := make([][]uint64, len(hists))
	for i, h := range hists {
		cols[i] = []uint64{
			meanToU64(h.mean()),
			h.valueAtQuantile(0.0),
			h.valueAtQuantile(0.1),
			h.valueAtQuantile(0.5),
			h.valueAtQuantile(0.9),
			h.valueAtQuantile(1.0),
		}
	}
	for r, label := range labels {
		fmt.Fprintf(&b, " %-4s │ %15s │ %17s │ %10s │ %17s │ %19s\n",
			label,
			durCell(cols[0][r]),
			durCell(cols[1][r]),
			durCell(cols[2][r]),
			tpCell(cols[3][r]),
			tpCell(cols[4][r]),
		)
	}
	b.WriteString("\n")
	return b.String()
}

// endInterval snapshots the per-stream byte counters for the JSON output and
// resets them for the next interval.
func (s *perfStats) endInterval(intervalStart, now time.Time) {
	start := intervalStart.Sub(s.start).Seconds()
	end := now.Sub(s.start).Seconds()
	seconds := now.Sub(intervalStart).Seconds()
	iv := intervalJSON{}
	var sumBytes uint64
	remaining := s.streams[:0]
	for _, e := range s.streams {
		bps := 0.0
		if seconds > 0 {
			bps = float64(e.bytes) * 8 / seconds
		}
		iv.streams = append(iv.streams, streamJSON{
			id: e.id, start: start, end: end, seconds: seconds,
			bytes: e.bytes, bitsPerSecond: bps, sender: e.sender,
		})
		if e.sender {
			sumBytes += e.bytes
		}
		e.bytes = 0
		if !e.finished {
			remaining = append(remaining, e)
		}
	}
	for i := len(remaining); i < len(s.streams); i++ {
		s.streams[i] = nil
	}
	s.streams = remaining
	sumBps := 0.0
	if seconds > 0 {
		sumBps = float64(sumBytes) * 8 / seconds
	}
	iv.sum = streamJSON{start: start, end: end, seconds: seconds, bytes: sumBytes, bitsPerSecond: sumBps, sender: sumBytes > 0}
	s.intervals = append(s.intervals, iv)
}

func (sj *streamJSON) marshal(withID bool) string {
	var b strings.Builder
	b.WriteString("{")
	if withID {
		fmt.Fprintf(&b, "\"id\":%d,", sj.id)
	}
	fmt.Fprintf(&b, "\"start\":%s,\"end\":%s,\"seconds\":%s,\"bytes\":%d,\"bits_per_second\":%s,\"sender\":%t}",
		fmtRustF64(sj.start), fmtRustF64(sj.end), fmtRustF64(sj.seconds), sj.bytes, fmtRustF64(sj.bitsPerSecond), sj.sender)
	return b.String()
}

// marshalJSON renders the iperf-like JSON document.
func (s *perfStats) marshalJSON() string {
	var b strings.Builder
	fmt.Fprintf(&b, "{\"start\":{\"timestamp\":{\"timesecs\":%d}},\"intervals\":[", s.startUnix)
	for i, iv := range s.intervals {
		if i > 0 {
			b.WriteString(",")
		}
		b.WriteString("{\"streams\":[")
		for j := range iv.streams {
			if j > 0 {
				b.WriteString(",")
			}
			b.WriteString(iv.streams[j].marshal(true))
		}
		b.WriteString("],\"sum\":")
		b.WriteString(iv.sum.marshal(false))
		b.WriteString("}")
	}
	b.WriteString("]}")
	return b.String()
}
EOF
echo done"}

