	for r, label := range labels {
		fmt.Fprintf(&b, " %-4s │ %15s │ %17s │ %10s │ %17s │ %19s\n",
			label,
			durCell(cols[0][r]),
			durCell(cols[1][r]),
			durCell(cols[2][r]),
			tpCell(cols[3][r]),
			tpCell(cols[4][r]),
		)
	}
	b.WriteString("\n")
	return b.String()
}

// endInterval snapshots the per-stream byte counters for the JSON output and
// resets them for the next interval.
func (s *perfStats) endInterval(intervalStart, now time.Time) {
	start := intervalStart.Sub(s.start).Seconds()
	end := now.Sub(s.start).Seconds()
	seconds := now.Sub(intervalStart).Seconds()
	iv := intervalJSON{}
	var sumBytes uint64
	remaining := s.streams[:0]
	for _, e := range s.streams {
		bps := 0.0
		if seconds > 0 {
			bps = float64(e.bytes) * 8 / seconds
		}
		iv.streams = append(iv.streams, streamJSON{
			id: e.id, start: start, end: end, seconds: seconds,
			bytes: e.bytes, bitsPerSecond: bps, sender: e.sender,
		})
		if e.sender {
			sumBytes += e.bytes
		}
		e.bytes = 0
		if !e.finished {
			remaining = append(remaining, e)
		}
	}
	for i := len(remaining); i < len(s.streams); i++ {
		s.streams[i] = nil
	}
	s.streams = remaining
	sumBps := 0.0
	if seconds > 0 {
		sumBps = float64(sumBytes) * 8 / seconds
	}
	iv.sum = streamJSON{start: start, end: end, seconds: seconds, bytes: sumBytes, bitsPerSecond: sumBps, sender: sumBytes > 0}
	s.intervals = append(s.intervals, iv)
}

func (sj *streamJSON) marshal(withID bool) string {
	var b strings.Builder
	b.WriteString("{")
	if withID {
		fmt.Fprintf(&b, "\"id\":%d,", sj.id)
	}
	fmt.Fprintf(&b, "\"start\":%s,\"end\":%s,\"seconds\":%s,\"bytes\":%d,\"bits_per_second\":%s,\"sender\":%t}",
		fmtRustF64(sj.start), fmtRustF64(sj.end), fmtRustF64(sj.seconds), sj.bytes, fmtRustF64(sj.bitsPerSecond), sj.sender)
	return b.String()
}

// marshalJSON renders the iperf-like JSON document.
func (s *perfStats) marshalJSON() string {
	var b strings.Builder
	fmt.Fprintf(&b, "{\"start\":{\"timestamp\":{\"timesecs\":%d}},\"intervals\":[", s.startUnix)
	for i, iv := range s.intervals {
		if i > 0 {
			b.WriteString(",")
		}
		b.WriteString("{\"streams\":[")
		for j := range iv.streams {
			if j > 0 {
				b.WriteString(",")
			}
			b.WriteString(iv.streams[j].marshal(true))
		}
		b.WriteString("],\"sum\":")
		b.WriteString(iv.sum.marshal(false))
		b.WriteString("}")
	}
	b.WriteString("]}")
	return b.String()
}
EOF
echo done

