			f.streamsBlockedBidi++
		}
	case "stop_sending":
		f.stopSending++
	case "stream":
		f.stream++
	}
}

type udpStats struct {
	datagrams, bytes, ios uint64
}

func (u *udpStats) String() string {
	return fmt.Sprintf("UdpStats { datagrams: %d, bytes: %d, ios: %d }", u.datagrams, u.bytes, u.ios)
}

// connStats mirrors the reference ConnectionStats structure.
type connStats struct {
	mu               sync.Mutex
	udpTx, udpRx     udpStats
	frameTx, frameRx frameStats
	rtt              time.Duration
	cwnd             uint64
	congestionEvents uint64
	lostPackets      uint64
	lostBytes        uint64
	sentPackets      uint64
	currentMTU       uint64

	sentSizes map[string]uint64 // "ptype/pnum" -> length, for lost byte accounting
	lastLoss  time.Time
	peer      string
}

func newConnStats() *connStats {
	return &connStats{
		rtt:        333 * time.Millisecond,
		cwnd:       12000,
		currentMTU: 1200,
		sentSizes:  map[string]uint64{},
	}
}

func (c *connStats) String() string {
	c.mu.Lock()
	defer c.mu.Unlock()
	return fmt.Sprintf("ConnectionStats { udp_tx: %s, udp_rx: %s, frame_tx: %s, frame_rx: %s, path: PathStats { rtt: %s, cwnd: %d, congestion_events: %d, lost_packets: %d, lost_bytes: %d, sent_packets: %d, sent_plpmtud_probes: 0, lost_plpmtud_probes: 0, black_holes_detected: 0, current_mtu: %d } }",
		c.udpTx.String(), c.udpRx.String(), c.frameTx.String(), c.frameRx.String(),
		fmtRustDurationDebug(c.rtt), c.cwnd, c.congestionEvents, c.lostPackets, c.lostBytes, c.sentPackets, c.currentMTU)
}

// connRegistry maps peer addresses to connection statistics.
type connRegistry struct {
	mu    sync.Mutex
	byKey map[string]*connStats
	all   []*connStats
}

func newConnRegistry() *connRegistry {
	return &connRegistry{byKey: map[string]*connStats{}}
}

func addrKey(ap netip.AddrPort) string {
	return netip.AddrPortFrom(ap.Addr().Unmap(), ap.Port()).String()
}

func (r *connRegistry) lookup(ap netip.AddrPort) *connStats {
	key := addrKey(ap)
	r.mu.Lock()
	defer r.mu.Unlock()
	if s, ok := r.byKey[key]; ok {
		return s
	}
	return nil
}

// waitFor looks up the statistics for a peer, waiting briefly for the
// connection_started event to be processed.
func (r *connRegistry) waitFor(ap netip.AddrPort) *connStats {
	for i := 0; i < 200; i++ {
		if s := r.lookup(ap); s != nil {
			return s
		}
		time.Sleep(5 * time.Millisecond)
	}
	s := newConnStats()
	r.mu.Lock()
	r.byKey[addrKey(ap)] = s
	r.mu.Unlock()
	return s
}

// qlogWriter writes qlog JSON-SEQ records to a file.
type qlogWriter struct {
	mu    sync.Mutex
	f     *os.File
	start time.Time
}

func newQlogWriter(path, title string) (*qlogWriter, error) {
	f, err := os.Create(path)
	if err != nil {
		return nil, err
	}
	w := &qlogWriter{f: f, start: time.Now()}
	header := fmt.Sprintf("\x1e{\"qlog_version\":\"0.3\",\"qlog_format\":\"JSON-SEQ\",\"title\":\"%s\",\"trace\":{\"vantage_point\":{\"type\":\"unknown\"},\"title\":\"%s\",\"configuration\":{\"time_offset\":0.0}}}\n", title, title)
	w.f.WriteString(header)
	return w, nil
}

func fmtRustF32(v float32) string {
	if v == 0 {
		return "0.0"
	}
	e := strconv.FormatFloat(float64(v), 'e', -1, 32)
	mant, expStr, _ := strings.Cut(e, "e")
	exp10, _ := strconv.Atoi(expStr)
	neg := strings.HasPrefix(mant, "-")
	mant = strings.TrimPrefix(mant, "-")
	digits := strings.Replace(mant, ".", "", 1)
	digits = strings.TrimRight(digits, "0")
	if digits == "" {
		digits = "0"
	}
	olength := len(digits)
	exponent := exp10 - (olength - 1)
	kk := olength + exponent
	var out string
	switch {
	case exponent >= 0 && kk <= 16:
		out = digits + strings.Repeat("0", exponent) + ".0"
	case 0 < kk && kk <= 16:
		out = digits[:kk] + "." + digits[kk:]
	case -5 < kk && kk <= 0:
		out = "0." + strings.Repeat("0", -kk) + digits
	case olength == 1:
		out = digits + "e" + strconv.Itoa(exponent)
	default:
		out = digits[:1] + "." + digits[1:] + "e" + strconv.Itoa(kk-1)
	}
	if neg {
		out = "-" + out
	}
	return out
}

func (w *qlogWriter) event(name, data, groupID string) {
	if w == nil {
		return
	}
	t := float32(time.Since(w.start).Seconds() * 1000)
	rec := fmt.Sprintf("\x1e{\"time\":%s,\"name\":\"%s\",\"data\":%s,\"group_id\":\"%s\"}\n", fmtRustF32(t), name, data, groupID)
	w.mu.Lock()
	w.f.WriteString(rec)
	w.mu.Unlock()
}

func (w *qlogWriter) close() {
	if w == nil {
		return
	}
	w.mu.Lock()
	w.f.Close()
	w.mu.Unlock()
}

// qlogSink is a slog.Handler that consumes the transport's qlog events to
// derive connection statistics and (optionally) to write a qlog file.
type qlogSink struct {
	level   slog.Level
	reg     *connRegistry
	writer  *qlogWriter
	stats   *connStats // per-connection (set by WithAttrs)
	groupID string
}

func newQlogSink(reg *connRegistry, writer *qlogWriter, frames bool) *qlogSink {
	lvl := quic.QLogLevelPacket
	if frames {
		lvl = quic.QLogLevelFrame
	}
	return &qlogSink{level: lvl, reg: reg, writer: writer}
}

func (h *qlogSink) Enabled(_ context.Context, l slog.Level) bool {
	return l >= h.level
}

func (h *qlogSink) WithAttrs(attrs []slog.Attr) slog.Handler {
	n := *h
	if n.stats == nil {
		n.stats = newConnStats()
		if n.reg != nil {
			n.reg.mu.Lock()
			n.reg.all = append(n.reg.all, n.stats)
			n.reg.mu.Unlock()
		}
	}
	for _, a := range attrs {
		if a.Key == "group_id" {
			n.groupID = a.Value.String()
		}
	}
	return &n
}

func (h *qlogSink) WithGroup(string) slog.Handler { return h }

type packetInfo struct {
	ptype  string
	pnum   uint64
	length uint64
	frames []slog.Value
}

func attrString(a slog.Attr) string {
	v := a.Value.Resolve()
	switch v.Kind() {
	case slog.KindString:
		return v.String()
	case slog.KindInt64:
		return strconv.FormatInt(v.Int64(), 10)
	case slog.KindUint64:
		return strconv.FormatUint(v.Uint64(), 10)
	}
	return v.String()
}

func attrUint(a slog.Attr) uint64 {
	v := a.Value.Resolve()
	switch v.Kind() {
	case slog.KindInt64:
		if v.Int64() < 0 {
			return 0
		}
		return uint64(v.Int64())
	case slog.KindUint64:
		return v.Uint64()
	}
	return 0
}

func (h *qlogSink) Handle(_ context.Context, r slog.Record) error {
	st := h.stats
	if st == nil {
		return nil
	}
	switch r.Message {
	case "connectivity:connection_started":
		var dstIP string
		var dstPort uint64
		r.Attrs(func(a slog.Attr) bool {
			switch a.Key {
			case "dst_ip":
				dstIP = attrString(a)
			case "dst_port":
				dstPort = attrUint(a)
			}
			return true
		})
		if ip, err := netip.ParseAddr(dstIP); err == nil && h.reg != nil {
			key := addrKey(netip.AddrPortFrom(ip, uint16(dstPort)))
			h.reg.mu.Lock()
			h.reg.byKey[key] = st
			h.reg.mu.Unlock()
			st.peer = key
		}
	case "transport:packet_sent", "transport:packet_received":
		var p packetInfo
		r.Attrs(func(a slog.Attr) bool {
			switch a.Key {
			case "header":
				for _, ha := range a.Value.Resolve().Group() {
					switch ha.Key {
					case "packet_type":
						p.ptype = attrString(ha)
					case "packet_number":
						p.pnum = attrUint(ha)
					}
				}
			case "raw":
				for _, ra := range a.Value.Resolve().Group() {
					if ra.Key == "length" {
						p.length = attrUint(ra)
					}
				}
			case "frames":
				if fv, ok := a.Value.Resolve().Any().([]slog.Value); ok {
					p.frames = fv
				}
			}
			return true
		})
		sent := r.Message == "transport:packet_sent"
		st.mu.Lock()
		var fs *frameStats
		if sent {
			st.udpTx.datagrams++
			st.udpTx.bytes += p.length
			st.udpTx.ios++
			st.sentPackets++
			st.sentSizes[p.ptype+"/"+strconv.FormatUint(p.pnum, 10)] = p.length
			if len(st.sentSizes) > 4096 {
				st.sentSizes = map[string]uint64{}
			}
			fs = &st.frameTx
		} else {
			st.udpRx.datagrams++
			st.udpRx.bytes += p.length
			st.udpRx.ios++
			fs = &st.frameRx
		}
		for _, fv := range p.frames {
			ftype, stype := "", ""
			for _, fa := range fv.Resolve().Group() {
				switch fa.Key {
				case "frame_type":
					ftype = attrString(fa)
				case "stream_type":
					stype = attrString(fa)
				}
			}
			fs.count(ftype, stype)
		}
		st.mu.Unlock()
		if h.writer != nil {
			var data string
			if sent {
				data = fmt.Sprintf("{\"header\":{\"packet_type\":\"%s\",\"packet_number\":%d,\"length\":%d}}", p.ptype, p.pnum, p.length)
			} else {
				data = fmt.Sprintf("{\"header\":{\"packet_type\":\"%s\",\"packet_number\":%d}}", p.ptype, p.pnum)
			}
			h.writer.event(r.Message, data, h.groupID)
		}
	case "recovery:metrics_updated":
		var fields []string
		var hasRTT bool
		var minRTT, smoothed, latest, variance time.Duration
		var cwnd, inflight int64
		var hasCwnd, hasInflight bool
		var ssthresh int64 = -1
		r.Attrs(func(a slog.Attr) bool {
			v := a.Value.Resolve()
			switch a.Key {
			case "min_rtt":
				minRTT, hasRTT = v.Duration(), true
			case "smoothed_rtt":
				smoothed = v.Duration()
			case "latest_rtt":
				latest = v.Duration()
			case "rtt_variance":
				variance = v.Duration()
			case "congestion_window":
				cwnd, hasCwnd = v.Int64(), true
			case "bytes_in_flight":
				inflight, hasInflight = v.Int64(), true
			case "ssthresh":
				ssthresh = v.Int64()
			}
			return true
		})
		st.mu.Lock()
		if hasRTT && smoothed > 0 {
			st.rtt = smoothed
		}
		if hasCwnd && cwnd > 0 {
			st.cwnd = uint64(cwnd)
		}
		st.mu.Unlock()
		if h.writer != nil {
			if hasRTT {
				fields = append(fields,
					fmt.Sprintf("\"min_rtt\":%s", fmtRustF32(float32(minRTT.Seconds()))),
					fmt.Sprintf("\"smoothed_rtt\":%s", fmtRustF32(float32(smoothed.Seconds()))),
					fmt.Sprintf("\"latest_rtt\":%s", fmtRustF32(float32(latest.Seconds()))),
					fmt.Sprintf("\"rtt_variance\":%s", fmtRustF32(float32(variance.Seconds()))))
			}
			if hasCwnd {
				fields = append(fields, fmt.Sprintf("\"congestion_window\":%d", cwnd))
			}
			if hasInflight {
				fields = append(fields, fmt.Sprintf("\"bytes_in_flight\":%d", inflight))
			}
			if hasCwnd {
				if ssthresh < 0 {
					fields = append(fields, fmt.Sprintf("\"ssthresh\":%d", uint64(math.MaxUint64)))
				} else {
					fields = append(fields, fmt.Sprintf("\"ssthresh\":%d", ssthresh))
				}
			}
			h.writer.event(r.Message, "{"+strings.Join(fields, ",")+"}", h.groupID)
		}
	case "recovery:packet_lost":
		var ptype string
		var pnum uint64
		r.Attrs(func(a slog.Attr) bool {
			if a.Key == "header" {
				for _, ha := range a.Value.Resolve().Group() {
					switch ha.Key {
					case "packet_type":
						ptype = attrString(ha)
					case "packet_number":
						pnum = attrUint(ha)
					}
				}
			}
			return true
		})
		st.mu.Lock()
		st.lostPackets++
		key := ptype + "/" + strconv.FormatUint(pnum, 10)
		if n, ok := st.sentSizes[key]; ok {
			st.lostBytes += n
			delete(st.sentSizes, key)
		}
		now := time.Now()
		if st.lastLoss.IsZero() || now.Sub(st.lastLoss) > st.rtt {
			st.congestionEvents++
		}
		st.lastLoss = now
		st.mu.Unlock()
		if h.writer != nil {
			data := fmt.Sprintf("{\"header\":{\"packet_type\":\"%s\",\"packet_number\":%d}}", ptype, pnum)
			h.writer.event(r.Message, data, h.groupID)
		}
	}
	return nil
}
