const (
	defaultStreamWindow = 1310720 // 1.25 MiB
	defaultConnWindow   = 128 << 20
	defaultSendWindow   = 8 * defaultStreamWindow
	maxWindow           = 1 << 60
)

func clampWindow(v uint64) int64 {
	if v == 0 {
		return -1
	}
	if v > maxWindow {
		return maxWindow
	}
	return int64(v)
}

// quicConfig builds the transport configuration.
func (o *commonOpts) quicConfig(tlsConf *tls.Config, sink *qlogSink) *quic.Config {
	cfg := &quic.Config{
		TLSConfig:               tlsConf,
		MaxBidiRemoteStreams:    100,
		MaxUniRemoteStreams:     100,
		MaxStreamReadBufferSize: defaultStreamWindow,
		MaxConnReadBufferSize:   defaultConnWindow,
		HandshakeTimeout:        30 * time.Second,
		MaxIdleTimeout:          30 * time.Second,
		MaxStreamWriteBufferSize: defaultSendWindow,
	}
	if o.streamReceiveWindow != nil {
		cfg.MaxStreamReadBufferSize = clampWindow(*o.streamReceiveWindow)
	}
	if o.receiveWindow != nil {
		cfg.MaxConnReadBufferSize = clampWindow(*o.receiveWindow)
	}
	if o.sendWindow != nil {
		cfg.MaxStreamWriteBufferSize = clampWindow(*o.sendWindow)
	}
	if sink != nil {
		cfg.QLogLogger = newSlogLogger(sink)
	}
	return cfg
}

// bindSocket binds a UDP socket and applies the buffer size options.
func bindSocket(addr netip.AddrPort, o *commonOpts) (*net.UDPConn, error) {
	network := "udp4"
	if addr.Addr().Is6() {
		network = "udp6"
	}
	udpAddr := net.UDPAddrFromAddrPort(addr)
	conn, err := net.ListenUDP(network, udpAddr)
	if err != nil {
		return nil, withContext(osError(err), "binding endpoint")
	}
	setBuffer(conn, "send", o.sendBufferSize)
	setBuffer(conn, "recv", o.recvBufferSize)
	return conn, nil
}

func setBuffer(conn *net.UDPConn, which string, desired uint64) {
	raw, err := conn.SyscallConn()
	if err != nil {
		return
	}
	opt := syscall.SO_SNDBUF
	if which == "recv" {
		opt = syscall.SO_RCVBUF
	}
	var actual int
	raw.Control(func(fd uintptr) {
		syscall.SetsockoptInt(int(fd), syscall.SOL_SOCKET, opt, int(int32(uint32(desired))))
		actual, _ = syscall.GetsockoptInt(int(fd), syscall.SOL_SOCKET, opt)
	})
	if uint64(actual) < desired {
		logWarn("perf", "Unable to set desired %s buffer size. Desired: %d, Actual: %d", which, desired, actual)
	}
}

