// selfSignedCert generates a certificate for "localhost".
func selfSignedCert() (tls.Certificate, error) {
	key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		return tls.Certificate{}, err
	}
	serial, _ := rand.Int(rand.Reader, new(big.Int).Lsh(big.NewInt(1), 127))
	tmpl := &x509.Certificate{
		SerialNumber:          serial,
		Subject:               pkix.Name{CommonName: "localhost"},
		NotBefore:             time.Now().Add(-time.Hour),
		NotAfter:              time.Now().Add(365 * 24 * time.Hour),
		DNSNames:              []string{"localhost"},
		KeyUsage:              x509.KeyUsageDigitalSignature,
		ExtKeyUsage:           []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth},
		BasicConstraintsValid: true,
	}
	der, err := x509.CreateCertificate(rand.Reader, tmpl, tmpl, &key.PublicKey, key)
	if err != nil {
		return tls.Certificate{}, err
	}
	return tls.Certificate{Certificate: [][]byte{der}, PrivateKey: key}, nil
}

// streamName formats a QUIC stream id like the reference implementation.
func streamName(id uint64) string {
	initiator := "client"
	if id&1 == 1 {
		initiator = "server"
	}
	dir := "bidirectional"
	if id&2 == 2 {
		dir = "unidirectional"
	}
	return fmt.Sprintf("%s %s stream %d", initiator, dir, id>>2)
}

// connErrorString renders a connection-level failure like quinn's ConnectionError.
func connErrorString(err error, locallyClosed bool) string {
	if locallyClosed {
		return "closed"
	}
	var appErr *quic.ApplicationError
	if errors.As(err, &appErr) {
		if appErr.Reason != "" {
			return fmt.Sprintf("closed by peer: %s (code %d)", appErr.Reason, appErr.Code)
		}
		return fmt.Sprintf("closed by peer: %d", appErr.Code)
	}
	msg := err.Error()
	switch {
	case strings.Contains(msg, "idle timeout"), strings.Contains(msg, "handshake timeout"):
		return "timed out"
	case strings.Contains(msg, "peer closed connection: NO_ERROR"):
		return "aborted by peer: the connection is being closed abruptly (code 0x0)"
	case strings.HasPrefix(msg, "peer closed connection"):
		return "aborted by peer: " + strings.TrimPrefix(msg, "peer closed connection: ")
	case strings.Contains(msg, "stateless reset"):
		return "reset by peer"
	}
	return msg
}

// isConnError reports whether a stream operation failed because the
// connection as a whole terminated.
func isConnError(err error) bool {
	var appErr *quic.ApplicationError
	if errors.As(err, &appErr) {
		return true
	}
	msg := err.Error()
	return strings.Contains(msg, "idle timeout") ||
		strings.Contains(msg, "peer closed connection") ||
		strings.Contains(msg, "connection closed") ||
		strings.Contains(msg, "stateless reset") ||
		strings.Contains(msg, "stream error code 9223372036854775807") ||
		strings.Contains(msg, "handshake timeout") ||
		strings.Contains(msg, "peer did not respond")
}

// readErrorString renders a stream read failure like quinn's ReadError.
func readErrorString(err error, locallyClosed bool) string {
	if locallyClosed || isConnError(err) {
		return "connection lost: " + connErrorString(err, locallyClosed)
	}
	var code quic.StreamErrorCode
	if errors.As(err, &code) {
		return fmt.Sprintf("stream reset by peer: error %d", uint64(code))
	}
	return err.Error()
}

// writeErrorString renders a stream write failure like quinn's WriteError.
func writeErrorString(err error, locallyClosed bool) string {
	if locallyClosed || isConnError(err) {
		return "connection lost: " + connErrorString(err, locallyClosed)
	}
	var code quic.StreamErrorCode
	if errors.As(err, &code) {
		return fmt.Sprintf("sending stopped by peer: error %d", uint64(code))
	}
	if strings.Contains(err.Error(), "reset stream") {
		return "sending stopped by peer: error 0"
	}
	return err.Error()
}
