// contextError wraps an error with a context message, rendered like anyhow's
// alternate ("{:#}") display: "context: cause".
type contextError struct {
	ctx   string
	cause error
}

func (e *contextError) Error() string { return e.ctx + ": " + e.cause.Error() }
func (e *contextError) Unwrap() error { return e.cause }

func withContext(err error, ctx string) error {
	if err == nil {
		return nil
	}
	return &contextError{ctx: ctx, cause: err}
}

// osError renders an OS error like Rust's io::Error display.
func osError(err error) error {
	var errno syscall.Errno
	if errors.As(err, &errno) {
		return fmt.Errorf("%s (os error %d)", capitalizeFirst(errno.Error()), int(errno))
	}
	var pe *os.PathError
	if errors.As(err, &pe) {
		return osError(pe.Err)
	}
	return err
