// resolveHost mirrors `ToSocketAddrs` on a "host:port" string.
func resolveHost(host string) (netip.AddrPort, error) {
	if ap, err := netip.ParseAddrPort(host); err == nil {
		return ap, nil
	}
	idx := strings.LastIndexByte(host, ':')
	if idx < 0 {
		return netip.AddrPort{}, errors.New("invalid socket address")
	}
	name, portStr := host[:idx], host[idx+1:]
	port, err := parseRustU16(portStr)
	if err != nil {
		return netip.AddrPort{}, errors.New("invalid port value")
	}
	if strings.HasPrefix(name, "[") && strings.HasSuffix(name, "]") {
		name = name[1 : len(name)-1]
	}
	ips, err := net.DefaultResolver.LookupIPAddr(context.Background(), name)
	if err != nil {
		var dnsErr *net.DNSError
		if errors.As(err, &dnsErr) {
			if dnsErr.IsNotFound {
				return netip.AddrPort{}, errors.New("failed to lookup address information: Name or service not known")
			}
			return netip.AddrPort{}, errors.New("failed to lookup address information: Temporary failure in name resolution")
		}
		return netip.AddrPort{}, errors.New("failed to lookup address information: " + err.Error())
	}
	if len(ips) == 0 {
		return netip.AddrPort{}, errors.New("failed to lookup address information: Name or service not known")
	}
	// Prefer IPv6 results, like getaddrinfo's default sorting on dual-stack hosts.
	sort.SliceStable(ips, func(i, j int) bool {
		return ips[i].IP.To4() == nil && ips[j].IP.To4() != nil
	})
	a, ok := netip.AddrFromSlice(ips[0].IP)
	if !ok {
		return netip.AddrPort{}, errors.New("invalid socket address")
	}
	return netip.AddrPortFrom(a.Unmap(), port), nil
}

// clientState is shared between the request drivers and the reporter.
type clientState struct {
