	if _, err := s.Write(hdr[:]); err != nil {
		return errors.New(writeErrorString(err, st.locallyClosed.Load()))
	}
	var entry *streamEntry
	remaining := st.uploadSize
	for remaining > 0 {
		n := uint64(len(st.uploadBuf))
		if n > remaining {
			n = remaining
