		if _, err := s.Write(st.uploadBuf[:n]); err != nil {
			return errors.New(writeErrorString(err, st.locallyClosed.Load()))
		}
		st.mu.Lock()
		if entry == nil {
			entry = st.stats.streamStarted(id, true)
		}
		entry.bytes += n
		st.mu.Unlock()
		remaining -= n
	}
	if waitAck {
		if err := s.Close(); err != nil {
			return errors.New(writeErrorString(err, st.locallyClosed.Load()))
		}
	} else {
		s.CloseWrite()
		if err := s.Flush(); err != nil {
			return errors.New(writeErrorString(err, st.locallyClosed.Load()))
		}
	}
	if st.uploadSize > 0 {
		d := time.Since(t0)
		st.mu.Lock()
		st.stats.recordUpload(d, st.uploadSize)
		if entry != nil {
			entry.finished = true
		}
		st.mu.Unlock()
