			return errors.New(readErrorString(err, st.locallyClosed.Load()))
		}
	}
	if total > 0 {
		now := time.Now()
		st.mu.Lock()
		st.stats.recordDownload(now.Sub(t0), first.Sub(t0), total)
		entry.finished = true
		st.mu.Unlock()
	}
	logDebug(clientTarget, "response finished on %s", streamName(id))
	return nil
}

func (st *clientState) requestBi(ctx context.Context) error {
	s, err := st.conn.NewStream(ctx)
	if err != nil {
		return errors.New(connErrorString(err, st.locallyClosed.Load()))
	}
	logDebug(clientTarget, "sending request on %s", streamName(uint64(s.ID())))
	if err := st.upload(s, false); err != nil {
		return err
	}
	if err := st.drain(s); err != nil {
		return withContext(err, "sending response")
	}
	s.Close()
	return nil
}

func (st *clientState) requestUni(ctx context.Context) error {
	s, err := st.conn.NewSendOnlyStream(ctx)
	if err != nil {
		return errors.New(connErrorString(err, st.locallyClosed.Load()))
	}
	logDebug(clientTarget, "sending request on %s", streamName(uint64(s.ID())))
	if err := st.upload(s, true); err != nil {
		return err
	}
	r, err := st.conn.AcceptStream(ctx)
	if err != nil {
		return errors.New(connErrorString(err, st.locallyClosed.Load()))
	}
	if err := st.drain(r); err != nil {
		return withContext(err, "sending response")
	}
	r.Close()
	return nil
}
