package main

import (
	"context"
	"crypto/tls"
	"encoding/binary"
	"errors"
	"fmt"
	"io"
	"net"
	"net/netip"
	"os"
	"os/signal"
	"runtime"
	"sort"
	"strings"
	"sync"
	"sync/atomic"
	"syscall"
	"time"

	"golang.org/x/net/quic"
)

const clientTarget = "perf::client"

type clientOpts struct {
	host         string
	ip           *netip.Addr
	localAddr    *netip.AddrPort
	uniRequests  uint64
	biRequests   uint64
	downloadSize uint64
	uploadSize   uint64
	duration     uint64
	interval     uint64
	json         string
	common       commonOpts
}

func parseClientOpts(pc *parsedCommand) *clientOpts {
	o := &clientOpts{host: "localhost:4433", common: parseCommonOpts(pc)}
	if len(pc.positional) > 0 {
		o.host = pc.positional[0]
	}
	if pc.has("ip") {
		a, _ := parseIPAddr(pc.get("ip", ""))
		o.ip = &a
	}
	if pc.has("local-addr") {
		a, _ := parseSocketAddr(pc.get("local-addr", ""))
		o.localAddr = &a
	}
	o.uniRequests, _ = parseRustU64(pc.get("uni-requests", "0"))
	o.biRequests, _ = parseRustU64(pc.get("bi-requests", "1"))
	o.downloadSize, _ = parseSize(pc.get("download-size", "1M"))
	o.uploadSize, _ = parseSize(pc.get("upload-size", "1M"))
	o.duration, _ = parseRustU64(pc.get("duration", "60"))
	o.interval, _ = parseRustU64(pc.get("interval", "1"))
	o.json = pc.get("json", "")
	return o
}

// resolveHost mirrors `ToSocketAddrs` on a "host:port" string.
func resolveHost(host string) (netip.AddrPort, error) {
	if ap, err := netip.ParseAddrPort(host); err == nil {
		return ap, nil
	}
	idx := strings.LastIndexByte(host, ':')
	if idx < 0 {
		return netip.AddrPort{}, errors.New("invalid socket address")
	}
	name, portStr := host[:idx], host[idx+1:]
	port, err := parseRustU16(portStr)
	if err != nil {
		return netip.AddrPort{}, errors.New("invalid port value")
	}
	if strings.HasPrefix(name, "[") && strings.HasSuffix(name, "]") {
		name = name[1 : len(name)-1]
	}
	ips, err := net.DefaultResolver.LookupIPAddr(context.Background(), name)
	if err != nil {
		var dnsErr *net.DNSError
		if errors.As(err, &dnsErr) {
			if dnsErr.IsNotFound {
				return netip.AddrPort{}, errors.New("failed to lookup address information: Name or service not known")
			}
			return netip.AddrPort{}, errors.New("failed to lookup address information: Temporary failure in name resolution")
		}
		return netip.AddrPort{}, errors.New("failed to lookup address information: " + err.Error())
	}
	if len(ips) == 0 {
		return netip.AddrPort{}, errors.New("failed to lookup address information: Name or service not known")
	}
	// Prefer IPv6 results, like getaddrinfo's default sorting on dual-stack hosts.
	sort.SliceStable(ips, func(i, j int) bool {
		return ips[i].IP.To4() == nil && ips[j].IP.To4() != nil
	})
	a, ok := netip.AddrFromSlice(ips[0].IP)
	if !ok {
		return netip.AddrPort{}, errors.New("invalid socket address")
	}
	return netip.AddrPortFrom(a.Unmap(), port), nil
}

// clientState is shared between the request drivers and the reporter.
type clientState struct {
	mu            sync.Mutex
	stats         *perfStats
	conn          *quic.Conn
	locallyClosed atomic.Bool
	uploadSize    uint64
	downloadSize  uint64
	uploadBuf     []byte
}

func runClient(pc *parsedCommand) error {
	o := parseClientOpts(pc)

	parts := strings.Split(o.host, ":")
	hostName := parts[0]
	port := uint16(443)
	if len(parts) > 1 {
		p, err := parseRustU16Plain(parts[1])
		if err != nil {
			return withContext(err, "parsing port")
		}
		port = p
	}

	var addr netip.AddrPort
	if o.ip != nil {
		addr = netip.AddrPortFrom(*o.ip, port)
	} else {
		a, err := resolveHost(o.host)
		if err != nil {
			return withContext(err, "resolving host")
		}
		addr = a
	}
	logInfo(clientTarget, "connecting to %s at %s", hostName, addr)

	var bind netip.AddrPort
	if o.localAddr != nil {
		bind = *o.localAddr
	} else if addr.Addr().Is6() {
		bind = netip.AddrPortFrom(netip.IPv6Unspecified(), 0)
	} else {
		bind = netip.AddrPortFrom(netip.IPv4Unspecified(), 0)
	}
	logInfo(clientTarget, "local addr %s", bind)

	sock, err := bindSocket(bind, &o.common)
	if err != nil {
		return err
	}
	defer sock.Close()

	if err := o.common.checkTransportBounds(); err != nil {
		return err
	}

	var qw *qlogWriter
	if o.common.qlog != "" {
		qw, err = newQlogWriter(o.common.qlog, "perf-client")
		if err != nil {
			return osError(err)
		}
		defer qw.close()
	}

	if bind.Addr().Is4() && addr.Addr().Is6() {
		return fmt.Errorf("invalid remote address: %s", addr)
	}

	// Install the interrupt handler early; it is only acted upon once the
	// connection is established.
	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, syscall.SIGINT)

	tlsConf := &tls.Config{
		InsecureSkipVerify: true,
		NextProtos:         []string{"perf"},
		ServerName:         hostName,
		MinVersion:         tls.VersionTLS13,
	}
	if klw := keyLogWriter(o.common.keylog); klw != nil {
		tlsConf.KeyLogWriter = klw
		defer klw.Close()
	}

	reg := newConnRegistry()
	var sink *qlogSink
	if o.common.connStats || qw != nil {
		sink = newQlogSink(reg, qw, o.common.connStats)
	}
	cfg := o.common.quicConfig(tlsConf, sink)

	ep, err := quic.NewEndpoint(sock, nil)
	if err != nil {
		return withContext(err, "creating endpoint")
	}

	ctx := context.Background()
	conn, err := ep.Dial(ctx, "udp", addr.String(), cfg)
	if err != nil {
		return withContext(errors.New(connErrorString(err, false)), "connecting")
	}
	logInfo(clientTarget, "established")

	start := time.Now()
	st := &clientState{
		stats:        newPerfStats(start),
		conn:         conn,
		uploadSize:   o.uploadSize,
		downloadSize: o.downloadSize,
		uploadBuf:    make([]byte, 1<<20),
	}

	var cs *connStats
	if o.common.connStats {
		cs = reg.waitFor(conn.RemoteAddr())
	}

	// Request drivers.
	var wg sync.WaitGroup
	for i := uint64(0); i < o.uniRequests; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for {
				if err := st.requestUni(ctx); err != nil {
					logError(clientTarget, "sending request failed: %s", err.Error())
					return
				}
			}
		}()
	}
	for i := uint64(0); i < o.biRequests; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for {
				if err := st.requestBi(ctx); err != nil {
					logError(clientTarget, "request failed: %s", err.Error())
					return
				}
			}
		}()
	}
	driversDone := make(chan struct{})
	go func() {
		wg.Wait()
		close(driversDone)
	}()

	// Reporting loop.
	deadline := time.NewTimer(time.Duration(o.duration)*time.Second + 200*time.Millisecond)
	defer deadline.Stop()
	intervalStart := time.Now()
	var tick <-chan time.Time
	var ticker *time.Ticker
	if o.interval > 0 {
		ticker = time.NewTicker(time.Duration(o.interval) * time.Second)
		defer ticker.Stop()
		tick = ticker.C
	} else {
		c := make(chan time.Time)
		go func() {
			for {
				runtime.Gosched()
				c <- time.Now()
			}
		}()
		tick = c
	}

	report := func() {
		now := time.Now()
		st.mu.Lock()
		out := st.stats.report(now)
		st.stats.endInterval(intervalStart, now)
		st.mu.Unlock()
		if cs != nil {
			out += cs.String() + "\n\n"
		}
		writeStdout(out)
		intervalStart = time.Now()
	}

	shutdown := func() {
		logInfo(clientTarget, "shutting down")
		st.locallyClosed.Store(true)
		conn.Abort(&quic.ApplicationError{Code: 0, Reason: "done"})
	}

loop:
	for {
		select {
		case <-tick:
			report()
		case <-deadline.C:
			shutdown()
			break loop
		case <-sigCh:
			shutdown()
			break loop
		case <-driversDone:
			break loop
		}
	}

	// Wait for in-flight requests to report their failures.
	select {
	case <-driversDone:
	case <-time.After(2 * time.Second):
	}

	if o.json != "" {
		st.mu.Lock()
		doc := st.stats.marshalJSON()
		st.mu.Unlock()
		if o.json == "-" {
			writeStdout(doc)
		} else if f, err := os.Create(o.json); err == nil {
			f.WriteString(doc)
			f.Close()
		}
	}

	closeCtx, cancel := context.WithTimeout(ctx, 1*time.Second)
	defer cancel()
	ep.Close(closeCtx)
	return nil
}

// parseRustU16Plain mirrors u16::from_str (used for the host port).
func parseRustU16Plain(s string) (uint16, error) {
	v, err := parseRustU64(s)
	if err != nil {
		return 0, err
	}
	if v > 65535 {
		return 0, errIntTooLarge
	}
	return uint16(v), nil
}

// upload writes the request header and payload, finishing the stream.
func (st *clientState) upload(s *quic.Stream, waitAck bool) error {
	id := uint64(s.ID())
	var hdr [8]byte
	binary.BigEndian.PutUint64(hdr[:], st.downloadSize)
	t0 := time.Now()
	if _, err := s.Write(hdr[:]); err != nil {
		return errors.New(writeErrorString(err, st.locallyClosed.Load()))
	}
	var entry *streamEntry
	remaining := st.uploadSize
	for remaining > 0 {
		n := uint64(len(st.uploadBuf))
		if n > remaining {
			n = remaining
		}
		if _, err := s.Write(st.uploadBuf[:n]); err != nil {
			return errors.New(writeErrorString(err, st.locallyClosed.Load()))
		}
		st.mu.Lock()
		if entry == nil {
			entry = st.stats.streamStarted(id, true)
		}
		entry.bytes += n
		st.mu.Unlock()
		remaining -= n
	}
	if waitAck {
		if err := s.Close(); err != nil {
			return errors.New(writeErrorString(err, st.locallyClosed.Load()))
		}
	} else {
		s.CloseWrite()
		if err := s.Flush(); err != nil {
			return errors.New(writeErrorString(err, st.locallyClosed.Load()))
		}
	}
	if st.uploadSize > 0 {
		d := time.Since(t0)
		st.mu.Lock()
		st.stats.recordUpload(d, st.uploadSize)
		if entry != nil {
			entry.finished = true
		}
		st.mu.Unlock()
	}
	logDebug(clientTarget, "upload finished on %s", streamName(id))
	return nil
}

// drain reads a response stream to completion, recording download metrics.
func (st *clientState) drain(s *quic.Stream) error {
	id := uint64(s.ID())
	t0 := time.Now()
	var first time.Time
	var total uint64
	var entry *streamEntry
	buf := make([]byte, 64<<10)
	for {
		n, err := s.Read(buf)
		if n > 0 {
			if total == 0 {
				first = time.Now()
			}
			total += uint64(n)
			st.mu.Lock()
			if entry == nil {
				entry = st.stats.streamStarted(id, false)
			}
			entry.bytes += uint64(n)
			st.mu.Unlock()
		}
		if err != nil {
			if err == io.EOF {
				break
			}
			return errors.New(readErrorString(err, st.locallyClosed.Load()))
		}
	}
	if total > 0 {
		now := time.Now()
		st.mu.Lock()
		st.stats.recordDownload(now.Sub(t0), first.Sub(t0), total)
		entry.finished = true
		st.mu.Unlock()
	}
	logDebug(clientTarget, "response finished on %s", streamName(id))
	return nil
}

func (st *clientState) requestBi(ctx context.Context) error {
	s, err := st.conn.NewStream(ctx)
	if err != nil {
		return errors.New(connErrorString(err, st.locallyClosed.Load()))
	}
	logDebug(clientTarget, "sending request on %s", streamName(uint64(s.ID())))
	if err := st.upload(s, false); err != nil {
		return err
	}
	if err := st.drain(s); err != nil {
		return withContext(err, "sending response")
	}
	s.Close()
	return nil
}

func (st *clientState) requestUni(ctx context.Context) error {
	s, err := st.conn.NewSendOnlyStream(ctx)
	if err != nil {
		return errors.New(connErrorString(err, st.locallyClosed.Load()))
	}
	logDebug(clientTarget, "sending request on %s", streamName(uint64(s.ID())))
	if err := st.upload(s, true); err != nil {
		return err
	}
	r, err := st.conn.AcceptStream(ctx)
	if err != nil {
		return errors.New(connErrorString(err, st.locallyClosed.Load()))
	}
	if err := st.drain(r); err != nil {
		return withContext(err, "sending response")
	}
	r.Close()
	return nil
}
EOF
echo done

