package main

import (
	"context"
	"crypto/tls"
	"crypto/x509"
	"encoding/binary"
	"encoding/pem"
	"errors"
	"fmt"
	"io"
	"net/netip"
	"os"
	"sync/atomic"
	"time"

	"golang.org/x/net/quic"
)

const serverTarget = "perf::server"

type serverOpts struct {
	listen netip.AddrPort
	key    string
	cert   string
	common commonOpts
}

func parseServerOpts(pc *parsedCommand) *serverOpts {
	o := &serverOpts{common: parseCommonOpts(pc)}
	o.listen, _ = parseSocketAddr(pc.get("listen", "[::]:4433"))
	o.key = pc.get("key", "")
	o.cert = pc.get("cert", "")
	return o
}

// pemIOError renders a PEM file access failure like rustls-pki-types.
func pemIOError(err error) error {
	return fmt.Errorf("I/O error: %s", osError(err).Error())
}

func isKeyBlock(t string) bool {
	switch t {
	case "PRIVATE KEY", "RSA PRIVATE KEY", "EC PRIVATE KEY":
		return true
	}
	return false
}

// loadCertificate reads the PEM private key and certificate chain.
func loadCertificate(keyPath, certPath string) (tls.Certificate, error) {
	keyData, err := os.ReadFile(keyPath)
	if err != nil {
		return tls.Certificate{}, withContext(pemIOError(err), "reading private key")
	}
	var keyBlock *pem.Block
	rest := keyData
	for {
		var b *pem.Block
		b, rest = pem.Decode(rest)
		if b == nil {
			break
		}
		if isKeyBlock(b.Type) {
			keyBlock = b
			break
		}
	}
	if keyBlock == nil {
		return tls.Certificate{}, withContext(errors.New("no items found"), "reading private key")
	}

	f, err := os.Open(certPath)
	if err != nil {
		return tls.Certificate{}, withContext(pemIOError(err), "reading certificate chain file")
	}
	certData, err := io.ReadAll(f)
	f.Close()
	if err != nil {
		return tls.Certificate{}, withContext(pemIOError(err), "reading certificate chain")
	}
	var chain [][]byte
	rest = certData
	for {
		var b *pem.Block
		b, rest = pem.Decode(rest)
		if b == nil {
			break
		}
		if b.Type == "CERTIFICATE" {
			chain = append(chain, b.Bytes)
		}
	}
	if len(chain) == 0 {
		rustPanic("called `Result::unwrap()` on an `Err` value: NoCertificatesPresented")
	}

	var priv interface{}
	switch keyBlock.Type {
	case "RSA PRIVATE KEY":
		priv, err = x509.ParsePKCS1PrivateKey(keyBlock.Bytes)
	case "EC PRIVATE KEY":
		priv, err = x509.ParseECPrivateKey(keyBlock.Bytes)
	default:
		priv, err = x509.ParsePKCS8PrivateKey(keyBlock.Bytes)
	}
	if err != nil {
		rustPanic("called `Result::unwrap()` on an `Err` value: General(\"invalid private key\")")
	}
	leaf, err := x509.ParseCertificate(chain[0])
	if err != nil {
		rustPanic("called `Result::unwrap()` on an `Err` value: InvalidCertificate(BadEncoding)")
	}
	cert := tls.Certificate{Certificate: chain, PrivateKey: priv, Leaf: leaf}
	if _, err := tls.X509KeyPair(pemEncodeChain(chain), pem.EncodeToMemory(keyBlock)); err != nil {
		rustPanic("called `Result::unwrap()` on an `Err` value: InconsistentKeys(KeyMismatch)")
	}
	return cert, nil
}

func pemEncodeChain(chain [][]byte) []byte {
	var out []byte
	for _, c := range chain {
		out = append(out, pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: c})...)
	}
	return out
}

// rustPanic emulates a Rust panic in the server setup code.
func rustPanic(msg string) {
	fmt.Fprintf(os.Stderr, "\nthread 'main' (%d) panicked at /workspace/perf/src/server.rs:58:10:\n%s\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n", os.Getpid(), msg)
	os.Exit(101)
}

func runServer(pc *parsedCommand) error {
	o := parseServerOpts(pc)

	var cert tls.Certificate
	if o.key != "" {
		c, err := loadCertificate(o.key, o.cert)
		if err != nil {
			return err
		}
		cert = c
	} else {
		c, err := selfSignedCert()
		if err != nil {
			return err
		}
		cert = c
	}

	var qw *qlogWriter
	if o.common.qlog != "" {
		var err error
		qw, err = newQlogWriter(o.common.qlog, "perf-server")
		if err != nil {
			return osError(err)
		}
		defer qw.close()
	}

	sock, err := bindSocket(o.listen, &o.common)
	if err != nil {
		return err
	}
	defer sock.Close()

	if err := o.common.checkTransportBounds(); err != nil {
		return err
	}

	tlsConf := &tls.Config{
		Certificates: []tls.Certificate{cert},
		NextProtos:   []string{"perf"},
		MinVersion:   tls.VersionTLS13,
	}
	if klw := keyLogWriter(o.common.keylog); klw != nil {
		tlsConf.KeyLogWriter = klw
		defer klw.Close()
	}

	reg := newConnRegistry()
	var sink *qlogSink
	if o.common.connStats || qw != nil {
		sink = newQlogSink(reg, qw, o.common.connStats)
	}
	cfg := o.common.quicConfig(tlsConf, sink)

	ep, err := quic.NewEndpoint(sock, cfg)
	if err != nil {
		return withContext(err, "creating endpoint")
	}
	logInfo(serverTarget, "listening on %s", sock.LocalAddr())

	ctx := context.Background()
	for {
		conn, err := ep.Accept(ctx)
		if err != nil {
			return withContext(err, "accepting connection")
		}
		var cs *connStats
		if o.common.connStats {
			cs = reg.waitFor(conn.RemoteAddr())
		}
		go handleConnection(ctx, conn, cs)
	}
}

type serverConn struct {
	conn   *quic.Conn
	closed atomic.Bool
}

func handleConnection(ctx context.Context, conn *quic.Conn, cs *connStats) {
	peer := conn.RemoteAddr()
	peer = netip.AddrPortFrom(peer.Addr().Unmap(), peer.Port())
	logDebug(serverTarget, "%s connected", peer)
	if cs != nil {
		go func() {
			for {
				time.Sleep(2 * time.Second)
				writeStdout(cs.String() + "\n\n")
			}
		}()
	}
	sc := &serverConn{conn: conn}
	for {
		s, err := conn.AcceptStream(ctx)
		if err != nil {
			sc.closed.Store(true)
			return
		}
		go sc.handleStream(ctx, s)
	}
}

func (sc *serverConn) handleStream(ctx context.Context, s *quic.Stream) {
	if err := sc.serve(ctx, s); err != nil {
		logError(serverTarget, "request failed: %s", err.Error())
	}
}

func (sc *serverConn) serve(ctx context.Context, s *quic.Stream) error {
	id := uint64(s.ID())
	var hdr [8]byte
	n, err := io.ReadFull(s, hdr[:])
	if err != nil {
		if err == io.EOF || err == io.ErrUnexpectedEOF {
			return withContext(fmt.Errorf("stream finished early (%d bytes read)", n), "reading request")
		}
		return withContext(errors.New(readErrorString(err, false)), "reading request")
	}
	size := binary.BigEndian.Uint64(hdr[:])
	logDebug(serverTarget, "got req for %d bytes on %s", size, streamName(id))

	buf := make([]byte, 64<<10)
	for {
		_, err := s.Read(buf)
		if err != nil {
			if err == io.EOF {
				break
			}
			return errors.New(readErrorString(err, false))
		}
	}
	logDebug(serverTarget, "finished reading %s", streamName(id))

	w := s
	if s.IsReadOnly() {
		w, err = sc.conn.NewSendOnlyStream(ctx)
		if err != nil {
			return withContext(errors.New(connErrorString(err, false)), "opening stream")
		}
	}
	wid := uint64(w.ID())
	zero := make([]byte, 1<<20)
	for size > 0 {
		n := uint64(len(zero))
		if n > size {
			n = size
		}
		if _, err := w.Write(zero[:n]); err != nil {
			return withContext(errors.New(writeErrorString(err, false)), "sending response")
		}
		size -= n
	}
	w.CloseWrite()
	if err := w.Flush(); err != nil {
		return withContext(errors.New(writeErrorString(err, false)), "sending response")
	}
	logDebug(serverTarget, "finished responding on %s", streamName(wid))
	w.Close()
	if w != s {
		s.Close()
	}
	return nil
}
