	"time"

	"golang.org/x/net/quic"
)

type wrap struct{ *net.UDPConn }

func main() {
	key, _ := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	tmpl := &x509.Certificate{SerialNumber: big.NewInt(1), Subject: pkix.Name{CommonName: "localhost"}, NotBefore: time.Now().Add(-time.Hour), NotAfter: time.Now().Add(24 * time.Hour)}
	der, _ := x509.CreateCertificate(rand.Reader, tmpl, tmpl, &key.PublicKey, key)
	cert := tls.Certificate{Certificate: [][]byte{der}, PrivateKey: key}
	h := slog.NewTextHandler(os.Stderr, &slog.HandlerOptions{Level: slog.Level(-4)})
	scfg := &quic.Config{TLSConfig: &tls.Config{Certificates: []tls.Certificate{cert}, NextProtos: []string{"perf"}}, QLogLogger: slog.New(h)}
	sc, err := net.ListenUDP("udp", &net.UDPAddr{IP: net.IPv6unspecified, Port: 4451})
	if err != nil {
		panic(err)
	}
	var spc net.PacketConn = sc
	if len(os.Args) > 1 && os.Args[1] == "wrap" {
		spc = &wrap{sc}
	}
	sep, err := quic.NewEndpoint(spc, scfg)
	if err != nil {
		panic(err)
	}
	go func() {
		c, err := sep.Accept(context.Background())
		fmt.Println("server accepted", c, err)
	}()
	cc, _ := net.ListenUDP("udp", &net.UDPAddr{IP: net.IPv4zero, Port: 0})
	var cpc net.PacketConn = cc
	if len(os.Args) > 1 && os.Args[1] == "wrap" {
		cpc = &wrap{cc}
	}
	cep, _ := quic.NewEndpoint(cpc, nil)
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()
	conn, err := cep.Dial(ctx, "udp", "127.0.0.1:4451", &quic.Config{TLSConfig: &tls.Config{InsecureSkipVerify: true, NextProtos: []string{"perf"}}})
	fmt.Println("client dial", conn, err)
}
EOF
